impl Solution {
    pub fn add_negabinary(arr1: Vec<i32>, arr2: Vec<i32>) -> Vec<i32> {
        let mut result = Vec::new();
        let mut carry = 0;
        let mut i = 0;
        let mut j = 0;

        while i < arr1.len() || j < arr2.len() || carry != 0 {
            let digit1 = if i < arr1.len() { arr1[i] } else { 0 };
            let digit2 = if j < arr2.len() { arr2[j] } else { 0 };

            let sum = digit1 + digit2 + carry;

            if sum == 0 {
                result.push(0);
                carry = 0;
            } else if sum == 1 {
                result.push(1);
                carry = 0;
            } else if sum == 2 {
                result.push(0);
                carry = 1;
            } else {
                result.push(1);
                carry = 1;
            }

            i += 1;
            j += 1;
        }

        result
    }
}

